insert into public.catalog_products(slug, name, kind, category_id, summary, unit, price_mode, base_price, cover_url, images, source, is_placeholder, needs_review, published, featured)
select t.slug, t.name, t.kind, c.id, t.summary, t.unit, t.price_mode, t.base_price, t.cover_url, t.images, t.source, t.is_placeholder, t.needs_review, t.published, t.featured
from t join public.catalog_categories c on c.slug = t.cat on conflict (slug) do nothing;
